fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cols: i32 = 12;
    let rows: i32 = 9;
    let cw: i32 = w / cols;
    let ch: i32 = h / rows;
    host::display::clear(0x000000);
    let mut gy: i32 = 0;
    while gy < rows {
        let mut gx: i32 = 0;
        while gx < cols {
            let id: i32 = gy * cols + gx;
            let period: i32 = 40 + hash(id * 7 + 1) % 50;
            let phase: i32 = hash(id * 13 + 5) % period;
            let beat: i32 = (t + phase) % period;
            if beat < period / 3 {
                host::display::fill_rect(gx * cw + 2, gy * ch + 2, cw - 4, ch - 4, 0x80ff40);
            } else {
                host::display::fill_rect(gx * cw + 2, gy * ch + 2, cw - 4, ch - 4, 0x102008);
            }
            gx = gx + 1;
        }
        gy = gy + 1;
    }
    host::display::present();
}
